import { useMemo, useState, useTransition } from 'react'

export function useFilteredList(items) {
  const [query, setQ] = useState('')
  const [filter, setFilter] = useState('')
  const [isPending, startTransition] = useTransition()
  const setQuery = (v) => { setQ(v); startTransition(() => setFilter(v)) }
  const results = useMemo(() => items.filter((i) => i.toLowerCase().includes(filter.toLowerCase())), [items, filter])
  return { query, setQuery, results, isPending }
}

