import { memo, useDeferredValue, useState } from 'react'

const Results = memo(function Results({ q, items }) {
  return <ul>{items.filter((i) => i.includes(q)).map((i) => <li key={i}>{i}</li>)}</ul>
})

export function SearchPage({ items }) {
  const [query, setQuery] = useState('')
  const deferred = useDeferredValue(query)
  const stale = query !== deferred
  return (
    <div>
      <input aria-label="search" value={query} onChange={(e) => setQuery(e.target.value)} />
      <div data-testid="results" style={{ opacity: stale ? 0.5 : 1 }}>
        <Results q={deferred} items={items} />
      </div>
    </div>
  )
}

