import { use } from 'react'

export function createCache(fetcher) {
  const map = new Map()
  return (key) => {
    if (!map.has(key)) map.set(key, fetcher(key))
    return map.get(key)
  }
}

export function Comments({ read, postId }) {
  const list = use(read(postId))
  return <ul>{list.map((c) => <li key={c.id}>{c.text}</li>)}</ul>
}

