export function classifyComponent({ usesState, usesEffects, hasEventHandlers, usesBrowserApi, readsDatabase, usesSecrets } = {}) {
  const client = !!(usesState || usesEffects || hasEventHandlers || usesBrowserApi)
  const server = !!(readsDatabase || usesSecrets)
  if (client && server) return 'conflict'
  if (client) return 'client'
  if (server) return 'server'
  return 'either'
}

