  expect(classifyComponent({ usesBrowserApi: true })).toBe('client')
})

test('data and secrets stay on the server', () => {
  expect(classifyComponent({ readsDatabase: true })).toBe('server')
  expect(classifyComponent({ usesSecrets: true })).toBe('server')
})

test('both means split it; nothing means either', () => {
  expect(classifyComponent({ readsDatabase: true, usesState: true })).toBe('conflict')
  expect(classifyComponent({})).toBe('either')
})

