import { render, screen, fireEvent, act } from '@testing-library/react'
import { expect, test } from 'vitest'
import { renderToString } from 'react-dom/server'
import { ClientTime } from './ClientTime'

const now = () => new Date(2026, 0, 1, 9, 5)

test('server HTML shows the placeholder', () => {
  expect(renderToString(<ClientTime now={now} />)).toBe('<p>--:--</p>')
})

test('shows the time after mount', () => {
  render(<ClientTime now={now} />)
  expect(screen.getByText('09:05')).toBeTruthy()
})

test('hydrates without a mismatch', async () => {
  const { hydrateRoot } = await import('react-dom/client')
  const el = document.createElement('div')
  el.innerHTML = renderToString(<ClientTime now={now} />)
  document.body.appendChild(el)
  const errors = []
  const orig = console.error
  console.error = (...a) => errors.push(a.join(' '))
  await act(async () => { hydrateRoot(el, <ClientTime now={now} />, { onRecoverableError: (e) => errors.push(String(e)) }) })
  console.error = orig
  expect(errors).toEqual([])
  expect(el.textContent).toBe('09:05')
})
